class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        count = defaultdict(int)
        count[0] = 1                    # 空前缀
        pre = res = 0
        for x in nums:
            pre += x
            res += count[pre - k]       # 先查
            count[pre] += 1             # 再存
        return res

from itertools import accumulate

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        seen, res = Counter({0: 1}), 0
        for s in accumulate(nums):
            res += seen[s - k]
            seen[s] += 1
        return res

